import{api,money,esc,messageStatus}from'./config.mjs';
import{LEGAL_VERSION,LEGAL_DATE,policyDocs,legalSources}from'./policies.mjs';
const $=s=>document.querySelector(s),app=$('#app'),KEY='hocco-message-client-v3';
try{localStorage.removeItem('hocco-message-client-v2')}catch{}
let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch{}if(!state?.orders)state={orders:[]};if(!Array.isArray(state.communityOrders))state.communityOrders=[];
let catalog=null,draft={name:'',text:'',phone:'',slot:1,socialPlatform:'instagram',socialHandle:''},toastTimer,requestToken=null,trackingPoll=null,communityFeedTimer=null,communityStatusTimer=null,communityCarouselTimer=null;
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Não foi possível salvar o acompanhamento neste navegador. Guarde o link privado.');return false}};
const toast=t=>{$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)};
const closeButton='<button class="close" type="button" aria-label="Fechar">×</button>';
function openDialog(content,onSubmit){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=content;document.body.append(d);d.querySelector('.close')?.addEventListener('click',()=>d.close());d.addEventListener('close',()=>d.remove());d.querySelector('form')?.addEventListener('submit',e=>{e.preventDefault();onSubmit?.(new FormData(e.target),d)});d.showModal()}
function badge(o){return `<span class="badge ${o.review==='rejected'?'red':o.delivery==='published'?'success':'orange'}">${esc(messageStatus(o))}</span>`}
const historyLabel=action=>({created:'Pedido recebido',approve:'Mensagem aprovada',reject:'Mensagem reprovada',pay:'Pagamento confirmado',refund:'Devolução registrada',publish:'Mensagem veiculada','payment-claimed':'Pagamento informado por você',reminder_sent:'Lembrete da ofensiva enviado',reminder_optout:'Lembretes cancelados'}[action]||'Pedido atualizado');
const token=()=>Array.from(crypto.getRandomValues(new Uint8Array(32))).map(x=>x.toString(16).padStart(2,'0')).join('');
const remember=(o,trackingToken,history)=>{const previous=state.orders.find(x=>x.code===o.code),entry={...o,trackingToken,history:history??previous?.history??[]};state.orders=state.orders.filter(x=>x.code!==o.code);state.orders.unshift(entry);save();return entry};
const previewText=()=>draft.socialHandle.trim()?`@${draft.socialHandle.trim().replace(/^@/,'')}${draft.text.trim()?' · '+draft.text.trim():''}`:'Sua mensagem';
const privateHash=(o,page='acompanhar')=>`${page}/${o.code}/${o.trackingToken}`;
async function loadCatalog(){try{catalog=await api('catalog');return true}catch(e){toast(e.message);return false}}
let renderVersion=0;
function registerActiveDay(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),map=Object.fromEntries(parts.map(x=>[x.type,x.value])),today=map.year+'-'+map.month+'-'+map.day,prev=new Date(Date.UTC(Number(map.year),Number(map.month)-1,Number(map.day))-86400000).toISOString().slice(0,10),p=state.profile||{};if(p.lastActiveDate===today)return;state.profile={...p,activeDays:p.lastActiveDate===prev?(p.activeDays||1)+1:1,lastActiveDate:today};try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}}
async function render(){registerActiveDay();const version=++renderVersion;document.querySelector('dialog')?.close();const path=location.hash.slice(1)||'inicio',parts=path.split('/');const avatar=document.querySelector('#header-profile-avatar');if(avatar){const selected=Math.max(1,Math.min(20,Number(String(state.profile?.avatar||'avatar-01').replace('avatar-',''))||1))-1;avatar.style.backgroundPosition=`${selected%5*25}% ${Math.floor(selected/5)*100/3}%`}document.querySelectorAll('[data-tab]').forEach(a=>a.classList.toggle('active',a.dataset.tab===parts[0]));if(policyDocs[path])return renderPolicy(path);if(parts[0]==='inicio')return renderHome();if(parts[0]==='comunidade-pagamento'&&parts[1]&&parts[2])return renderCommunityPayment(parts[1],parts[2],version);if(parts[0]==='perfil')return renderProfile();if(parts[0]==='controle'){app.innerHTML='<div class="empty"><h2>O controle tem uma área própria.</h2><p>O acesso é exclusivo da equipe autorizada.</p><a class="btn" href="#enviar">Voltar ao Hocco Message</a></div>';return}if(parts[0]==='acompanhar'&&parts.length===1)return renderLookup();if(['acompanhar','pagamento'].includes(parts[0])&&parts[1]){app.innerHTML='<div class="empty">Consultando seu pedido…</div>';try{if(parts[0]==='pagamento'&&!catalog)await loadCatalog();const saved=state.orders.find(o=>o.code===parts[1]),key=parts[2]||saved?.trackingToken;if(!key)throw Error('Use o link privado completo recebido ao criar o pedido.');const d=await api('lookup',{code:parts[1],trackingToken:key});if(version!==renderVersion)return;const o=remember(d.order,key,d.history||[]);return parts[0]==='pagamento'?renderCheckout(o):renderOrder(o,d.history||[])}catch(e){if(version!==renderVersion)return;app.innerHTML=`<div class="empty"><h2>Não foi possível abrir o pedido.</h2><p>${esc(e.message)}</p><a href="#acompanhar" class="btn secondary">Voltar</a></div>`;return}}if(!catalog){app.innerHTML='<div class="empty">Preparando o Hocco Message…</div>';await loadCatalog();if(version!==renderVersion)return}renderCompose()}
const avatarCount=20;
function avatarArt(index){const safe=Math.max(0,Math.min(avatarCount-1,Number(index)||0)),col=safe%5,row=Math.floor(safe/5),x=col*25,y=(row*100/3).toFixed(3);return `<span class="avatar-portrait" aria-hidden="true" style="background-position:${x}% ${y}%"></span>`}
function renderProfile(){const p=state.profile||{},orders=state.orders||[],published=orders.filter(o=>o.delivery==='published').length,latest=orders.slice().sort((a,b)=>Date.parse(b.created_at||0)-Date.parse(a.created_at||0)),recent=latest.slice(0,2),streak=p.activeDays||1,selected=Math.max(0,Math.min(19,Number(String(p.avatar||'avatar-01').replace('avatar-',''))-1||0)),history=recent.length?recent.map(o=>`<a class="profile-history-card" href="#${privateHash(o)}"><span class="profile-history-bar" aria-hidden="true"></span><span class="profile-history-copy"><strong>| ${esc(o.message)}</strong><small>${esc(o.social_platform==='tiktok'?'TikTok':'Instagram')} · @${esc(o.social_handle||'')}</small></span><span class="profile-history-status">${badge(o)}<small>${o.created_at?new Date(o.created_at).toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'}):'Data não disponível'}</small></span><span class="profile-history-arrow" aria-hidden="true">›</span></a>`).join(''):`<div class="profile-history-empty"><strong>Sua história começa aqui.</strong><span>Quando você enviar um recado, o status e o histórico aparecerão nesta área.</span><a class="btn secondary small" href="/#enviar">Enviar meu primeiro recado</a></div>`;app.innerHTML=`<section class="profile-screen"><div class="profile-heading"><div class="eyebrow">HOCCO MESSAGE</div><h1>Meu perfil</h1><p>Sua jornada no Reality da HOCCO.</p></div><form id="profile-form"><section class="profile-card" aria-label="Dados do perfil"><button class="profile-avatar-button" type="button" id="choose-profile-avatar" aria-label="Escolher figurante">${avatarArt(selected)}<span class="profile-edit-mark" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="m12 5 2.2 4.5 5 .7-3.6 3.5.9 5-4.5-2.4-4.5 2.4.9-5-3.6-3.5 5-.7z"/></svg></span></button><div class="profile-identity"><label class="sr-only" for="profile-name">Nome do perfil</label><input id="profile-name" maxlength="40" value="${esc(p.name||'')}" placeholder="Seu nome" autocomplete="nickname"><label class="sr-only" for="profile-username">Seu nome de perfil com @</label><input id="profile-username" maxlength="25" value="${esc(p.username?'@'+p.username:'')}" placeholder="@seuperfil" autocomplete="username" inputmode="text" pattern="@?[A-Za-z0-9._]{3,24}" title="Use de 3 a 24 letras, números, pontos ou sublinhados."><span class="profile-active"><i aria-hidden="true"></i> Perfil ativo</span></div><button class="profile-save" type="submit">Salvar perfil</button><small class="profile-photo-hint">Este perfil, avatar e histórico ficam neste aparelho e neste navegador. Não há login nem sincronização entre aparelhos. Para consultar um pedido em outro dispositivo, use o link privado.</small></section></form><div class="profile-stats" aria-label="Resumo da sua atividade"><article class="profile-stat stat-purple"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11.5a7.5 7.5 0 0 1-7.5 7.5H6l-3 2v-5.5a7.5 7.5 0 1 1 17.5-4Z"/></svg><span>Mensagens</span><strong>${String(orders.length).padStart(2,'0')}</strong></article><article class="profile-stat stat-orange"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 3.8v16.4L20 12 5 3.8Z"/></svg><span>Veiculadas</span><strong>${String(published).padStart(2,'0')}</strong></article><article class="profile-stat stat-lime"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 22s8-4.5 8-12V5l-8-3-8 3v5c0 7.5 8 12 8 12Z"/><path d="m9 12 2 2 4-4"/></svg><span>Ofensiva</span><strong>${String(streak).padStart(2,'0')} <small>${streak===1?'dia':'dias'}</small></strong></article></div><a class="profile-send-button" href="/#enviar"><svg viewBox="0 0 24 24"><path d="m22 2-7 20-4-9-9-4 20-7ZM22 2 11 13"/></svg>Enviar nova mensagem <span aria-hidden="true">›</span></a><div class="profile-history-heading"><h2>Meu histórico</h2><a href="#acompanhar">Ver tudo <span aria-hidden="true">›</span></a></div><div class="profile-history">${history}</div><section class="profile-reset"><button class="profile-reset-button" id="reset-profile" type="button">Resetar</button></section></section>`;$('#choose-profile-avatar').onclick=()=>{let pendingAvatar=selected+1;openDialog(`<div class="dialog-head"><div><div class="eyebrow">MEU PERFIL</div><h2>Figurantes</h2><p>Escolha um avatar para continuar.</p></div>${closeButton}</div><div class="avatar-picker" role="listbox" aria-label="Escolha um avatar">${Array.from({length:avatarCount},(_,i)=>`<button type="button" class="avatar-choice ${i===selected?'selected':''}" data-avatar="${i+1}" role="option" aria-selected="${i===selected}" aria-label="Figurante ${i+1}">${avatarArt(i)}</button>`).join('')}</div><button class="btn full avatar-confirm" id="confirm-avatar" type="button">Escolher</button>`);const dialog=document.querySelector('dialog');dialog?.querySelectorAll('[data-avatar]').forEach(button=>button.onclick=()=>{pendingAvatar=Number(button.dataset.avatar);dialog.querySelectorAll('[data-avatar]').forEach(option=>{const chosen=Number(option.dataset.avatar)===pendingAvatar;option.classList.toggle('selected',chosen);option.setAttribute('aria-selected',String(chosen))})});dialog?.querySelector('#confirm-avatar')?.addEventListener('click',()=>{state.profile={...p,avatar:`avatar-${String(pendingAvatar).padStart(2,'0')}`};if(!save()){state.profile={...p};toast('Não foi possível salvar este avatar neste aparelho.');return}const trigger=$('#choose-profile-avatar');trigger.innerHTML=avatarArt(pendingAvatar-1)+'<span class="profile-edit-mark" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="m12 5 2.2 4.5 5 .7-3.6 3.5.9 5-4.5-2.4-4.5 2.4.9-5-3.6-3.5 5-.7z"/></svg></span>';dialog.close()});};$('#profile-form').onsubmit=e=>{e.preventDefault();const typed=$('#profile-name').value.trim().slice(0,40),raw=$('#profile-username').value.trim().replace(/^@+/,''),valid=/^[A-Za-z0-9._]{3,24}$/.test(raw);if(raw&&!valid){toast('Use de 3 a 24 letras, números, pontos ou sublinhados no @.');return}state.profile={...p,name:typed||'Minha área',username:raw,avatar:state.profile?.avatar||p.avatar||'avatar-01',activeDays:streak,lastActiveDate:p.lastActiveDate};if(!save())return;toast('Perfil salvo neste aparelho.')};$('#reset-profile').onclick=async()=>{if(!confirm('Isso apagará seus dados, pedidos e histórico deste perfil, além de zerar sua ofensiva. Mensagens já publicadas nos vídeos continuam lá. Esta ação não pode ser desfeita. Continuar?'))return;const button=$('#reset-profile');button.disabled=true;button.textContent='Apagando…';try{const owned=orders.filter(o=>/^HM-26-[A-F0-9]{12}$/.test(o.code||'')&&/^[a-f0-9]{64}$/.test(o.trackingToken||'')).map(o=>({code:o.code,trackingToken:o.trackingToken}));await api('customer.reset',{orders:owned});localStorage.removeItem(KEY);state={orders:[]};location.hash='#perfil';renderProfile();toast('Perfil e pedidos encontrados foram apagados.')}catch(error){toast(error.message||'Não foi possível resetar o app.');button.disabled=false;button.textContent='Resetar'}}}
function renderHome(){
 if(communityFeedTimer)clearInterval(communityFeedTimer);if(communityCarouselTimer)clearInterval(communityCarouselTimer);
 app.innerHTML=`<section class="home-hero"><div class="home-copy"><div class="eyebrow">Série documental HOCCO · produzida em tempo real</div><h1 class="home-title">Sua mensagem<br><em>dentro do Reality da HOCCO.</em></h1><p class="lead">Após a curadoria e a confirmação do Pix, sua mensagem aparece no vídeo oficial da série documental HOCCO, produzida em tempo real.</p><div class="home-actions"><a class="btn" href="#enviar">Enviar meu recado <span aria-hidden="true">→</span></a><a class="btn sponsor-cta" href="/ir-alem/#patrocinadores">Conheça quem financia <b aria-hidden="true">→</b></a><a class="btn secondary" href="/cliente/#acompanhar">Acompanhar mensagem</a><a class="btn youtube-icon-link" href="https://www.youtube.com/@hoccpov" target="_blank" rel="noopener noreferrer" aria-label="Abrir o canal oficial da HOCCO no YouTube" title="Canal oficial da HOCCO no YouTube"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M23.5 6.2a3 3 0 0 0-2.1-2.1C19.5 3.6 12 3.6 12 3.6s-7.5 0-9.4.5A3 3 0 0 0 .5 6.2 31 31 0 0 0 0 12a31 31 0 0 0 .5 5.8 3 3 0 0 0 2.1 2.1c1.9.5 9.4.5 9.4.5s7.5 0 9.4-.5a3 3 0 0 0 2.1-2.1A31 31 0 0 0 24 12a31 31 0 0 0-.5-5.8ZM9.6 15.6V8.4l6.2 3.6-6.2 3.6Z"/></svg></a></div><div class="home-points"><span>Seu recado dentro do episódio</span><span>Curadoria e confirmação antes da publicação</span></div></div><div class="home-art"><img src="/assets/figurantes-3d.webp" alt="Avatares 3D dos figurantes da HOCCO reunidos na página inicial"><span class="home-sticker">Pessoas reais<br>histórias reais</span><span class="home-figurante" aria-hidden="true"></span></div></section><section class="community-section" aria-labelledby="community-title"><div class="community-heading"><div><div class="eyebrow">HOCCO · JUNTO NA HISTÓRIA</div><h2 id="community-title">Comunidade</h2></div><div class="community-controls"><button class="community-arrow" type="button" id="community-prev" aria-label="Mensagem anterior"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 18-6-6 6-6"/></svg></button><button class="community-arrow" type="button" id="community-next" aria-label="Próxima mensagem"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg></button></div></div><div class="community-carousel" id="community-carousel"><div class="community-track" id="community-track" aria-live="polite"><div class="community-empty">Carregando mensagens da comunidade…</div></div></div><div class="community-bottom"><p>As mensagens aprovadas ficam disponíveis por 24 horas.</p><button class="btn community-send" id="community-send" type="button"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M21 3 10 14M21 3l-7 18-4-7-7-4 18-7Z"/></svg>Deixar uma mensagem</button></div></section>`;
 $('#community-send').onclick=openCommunityComposer;$('#community-prev').onclick=()=>moveCommunity(-1);$('#community-next').onclick=()=>moveCommunity(1);
 loadCommunityFeed();communityFeedTimer=setInterval(loadCommunityFeed,60000);
}
function relativeCommunityTime(value){const minutes=Math.max(0,Math.floor((Date.now()-Date.parse(value||Date.now()))/60000));return minutes<1?'agora':minutes<60?`há ${minutes} min`:`há ${Math.floor(minutes/60)} h`}
function communityExpiry(value){const minutes=Math.max(0,Math.ceil((Date.parse(value||Date.now())-Date.now())/60000));return minutes<60?`Expira em ${minutes} min`:`Expira em ${Math.floor(minutes/60)} h`}
async function loadCommunityFeed(){const track=$('#community-track');if(!track)return;try{const result=await api('community.feed'),messages=Array.isArray(result.messages)?result.messages:[];track.innerHTML=messages.length?messages.map(post=>`<article class="community-card"><div class="community-card-head">${avatarArt(Math.max(0,Math.min(19,Number(post.avatar_index||1)-1)))}<div><strong>${esc(post.member_name)}</strong><span>@${esc(post.member_username)} · ${relativeCommunityTime(post.published_at)}</span></div><span class="community-expiry">${communityExpiry(post.expires_at)}</span></div><p>${esc(post.message)}</p></article>`).join(''):'<div class="community-empty">As mensagens da comunidade aparecem aqui depois da curadoria.</div>';track.dataset.index='0';track.scrollTo({left:0,behavior:'instant'});if(communityCarouselTimer)clearInterval(communityCarouselTimer);if(messages.length>1){communityCarouselTimer=setInterval(()=>{if(document.hidden||document.activeElement?.closest('.community-section'))return;moveCommunity(1)},7000)}}catch{track.innerHTML='<div class="community-empty">As mensagens da comunidade não puderam ser carregadas agora.</div>'}}
function moveCommunity(direction){const track=$('#community-track');if(!track)return;const cards=[...track.querySelectorAll('.community-card')];if(cards.length<2)return;let index=Number(track.dataset.index||0)+direction;if(index>=cards.length)index=0;if(index<0)index=cards.length-1;track.dataset.index=String(index);track.scrollTo({left:cards[index].offsetLeft,behavior:'smooth'})}
function openCommunityComposer(){const profile=state.profile||{},name=String(profile.name||'').trim(),username=String(profile.username||'').replace(/^@+/,''),avatar=Number(String(profile.avatar||'avatar-01').replace('avatar-',''));if(!name||! /^[A-Za-z0-9._]{3,24}$/.test(username)){toast('Complete seu nome e @ em Meu perfil para enviar.');location.hash='#perfil';return}openDialog(`<div class="dialog-head"><div><div class="eyebrow">HOCCO · COMUNIDADE</div><h2>Deixe sua mensagem</h2><p>Ela aparece depois da confirmação do Pix e da curadoria.</p></div>${closeButton}</div><form id="community-form"><div class="community-profile-summary">${avatarArt(Math.max(0,Math.min(19,avatar-1)))}<div><strong>${esc(name)}</strong><span>@${esc(username)}</span></div></div><div class="field"><label for="community-message">Sua mensagem</label><textarea id="community-message" name="message" maxlength="180" required placeholder="Escreva uma mensagem para a comunidade…"></textarea><div class="field-foot"><small>Até 180 caracteres.</small><span id="community-counter">0/180</span></div></div><p class="hint">Sua mensagem será analisada pela curadoria da HOCCO antes de aparecer.</p><div class="error" id="community-error" role="alert"></div><button class="btn full" type="submit">Continuar</button></form>`);const dialog=document.querySelector('dialog'),input=dialog?.querySelector('#community-message');input?.addEventListener('input',()=>{dialog.querySelector('#community-counter').textContent=input.value.length+'/180'});dialog?.querySelector('#community-form')?.addEventListener('submit',async e=>{e.preventDefault();const button=dialog.querySelector('button[type="submit"]'),message=input.value.trim();if(!message)return;button.disabled=true;button.textContent='Preparando o pagamento…';try{const trackingToken=token(),result=await api('community.create',{name,username,avatar,message,trackingToken});const entry={...result.post,trackingToken,pix:result.pix};state.communityOrders=[entry,...(state.communityOrders||[]).filter(x=>x.code!==entry.code)];save();dialog.close();location.hash=`#comunidade-pagamento/${entry.code}/${trackingToken}`}catch(error){dialog.querySelector('#community-error').textContent=error.message;button.disabled=false;button.textContent='Continuar'}})}
function rememberCommunity(post,trackingToken,pix){const entry={...post,trackingToken,pix};state.communityOrders=[entry,...(state.communityOrders||[]).filter(x=>x.code!==entry.code)];save();return entry}
function communityStatus(post){if(post.review==='rejected')return post.payment==='refunded'?'Mensagem recusada · valor devolvido':'Mensagem recusada';if(post.published_at&&Date.parse(post.expires_at)>Date.now())return'Visível na Comunidade';if(post.payment==='confirmed'&&post.review==='pending')return'Pix confirmado · em curadoria';if(post.payment==='pending'&&post.payment_claimed)return'Pagamento informado · em conferência';if(post.review==='approved'&&post.payment==='pending')return'Aguardando confirmação do Pix';return'Em curadoria'}
async function renderCommunityPayment(code,trackingToken,version){
 if(communityStatusTimer)clearInterval(communityStatusTimer);
 app.innerHTML='<section class="narrow"><div class="empty">Abrindo o acompanhamento da Comunidade…</div></section>';
 try{
  if(!/^HC-CM-[A-F0-9]{12}$/.test(code)||! /^[a-f0-9]{64}$/.test(trackingToken))throw Error('Link privado da mensagem inválido.');
  const result=await api('community.lookup',{code,trackingToken});
  if(version!==renderVersion)return;
  const post=rememberCommunity(result.post,trackingToken),rejected=post.review==='rejected',active=post.published_at&&Date.parse(post.expires_at)>Date.now();
  const paymentPanel=!rejected&&post.payment==='pending'
   ? '<div class="payment-method"><div class="row"><h2>Pagamento</h2><span class="badge">Mercado Pago</span></div><div class="community-payment-total row"><span>Uma mensagem na Comunidade</span><strong>'+money(post.price_cents)+'</strong></div><button class="btn purple full" id="mp-checkout-community">Continuar para pagamento →</button><p class="hint">Na próxima etapa, você verá as formas disponíveis, como Pix ou cartão. Não precisa ter conta no Mercado Pago.</p><p class="hint">O Hocco atualizará o pedido automaticamente quando o pagamento for confirmado. Depois, a mensagem seguirá para curadoria.</p></div>'
   :!rejected&&post.payment==='confirmed'
    ?'<div class="note"><strong>Pagamento confirmado.</strong> A mensagem segue para a curadoria. Acompanhe as atualizações por este link.</div>'
    :post.payment==='refunded'?'<div class="note">Pagamento devolvido.</div>':'';
  app.innerHTML=`<section class="narrow checkout community-checkout"><div class="eyebrow">HOCCO · Comunidade</div><h1 class="section-title">Sua mensagem<br><em>${active?'está na Comunidade':'a caminho'}.</em></h1><p class="subheading">${esc(communityStatus(post))}</p><div class="paper"><div class="community-profile-summary">${avatarArt(Math.max(0,Math.min(19,Number(post.avatar_index||1)-1)))}<div><strong>${esc(post.member_name)}</strong><span>@${esc(post.member_username)}</span></div></div><p class="quote">${esc(post.message)}</p>${post.published_at?'<p class="hint">'+(active?'Disponível até ':'Esta mensagem expirou na Comunidade · ')+new Date(post.expires_at).toLocaleString('pt-BR')+'</p>':''}${rejected?'<div class="note"><strong>Mensagem recusada</strong><p>'+esc(post.reason||'A equipe decidiu não publicar esta mensagem.')+'</p>'+(post.payment==='confirmed'?'A equipe registrará a devolução.':post.payment==='refunded'?'Devolução registrada.':'')+'</div>':''}</div>${paymentPanel}<a class="btn secondary full" href="/#inicio">Voltar à página inicial</a><button class="btn ghost full" id="community-copy-link">Copiar link privado</button><p class="hint"><a href="#termos">Ver termos e política de reembolso</a></p></section>`;
  $('#community-copy-link')?.addEventListener('click',()=>copy(location.origin+location.pathname+'#comunidade-pagamento/'+code+'/'+trackingToken));
  $('#mp-checkout-community')?.addEventListener('click',async e=>{const button=e.currentTarget;button.disabled=true;button.textContent='Abrindo pagamento…';try{const checkout=await api('payment.checkout',{kind:'community',code,trackingToken});location.assign(checkout.checkoutUrl)}catch(error){button.disabled=false;button.textContent='Continuar para pagamento →';toast(error.message)}});
  communityStatusTimer=setInterval(async()=>{if(location.hash!=='#comunidade-pagamento/'+code+'/'+trackingToken)return;try{const latest=await api('community.lookup',{code,trackingToken});if(latest.post.updated_at!==post.updated_at||latest.post.review!==post.review||latest.post.payment!==post.payment)await renderCommunityPayment(code,trackingToken,version)}catch{}},25000);
 }catch(error){if(version!==renderVersion)return;app.innerHTML='<div class="empty"><h2>Não foi possível abrir a mensagem.</h2><p>'+esc(error.message)+'</p><a href="/#inicio" class="btn secondary">Voltar</a></div>'}
}
function renderCheckout(o){
 const pending=o.payment==='pending'&&o.review!=='rejected'&&o.delivery!=='published';
 const paymentPanel=pending
  ? '<div class="payment-method"><div class="row"><h2>Pagamento</h2><span class="badge">Mercado Pago</span></div><div class="community-payment-total row"><span>Uma mensagem · posição '+esc(String(o.slot))+'</span><strong>'+money(o.price_cents)+'</strong></div><button class="btn purple full" id="mp-checkout-order">Continuar para pagamento →</button><p class="hint">Na próxima etapa, você verá as formas disponíveis, como Pix ou cartão. Não precisa ter conta no Mercado Pago.</p><p class="hint">Você será direcionado ao ambiente do Mercado Pago. O Hocco atualizará o pedido automaticamente após a confirmação. Seu recado ainda passa pela curadoria.</p></div>'
  :o.payment==='confirmed'
   ?'<div class="note"><strong>Pagamento confirmado automaticamente.</strong> Acompanhe aqui as atualizações da curadoria e da veiculação.</div>'
   :o.payment==='refunded'?'<div class="note">O pagamento foi devolvido.</div>':'';
 app.innerHTML=`<section class="narrow checkout"><div class="eyebrow">Hocco Message · pagamento</div><h1 class="section-title">Pagamento<br><em>do seu recado.</em></h1><p class="subheading">Pedido ${esc(o.code)} · posição ${o.slot}</p><div class="paper"><div class="row"><strong>${esc(o.name)}</strong><span class="badge">${esc(o.episode)}</span></div><p class="hint">Publicação até ${o.publication_deadline?new Date(o.publication_deadline).toLocaleString('pt-BR'):'a definir'} · ${o.display_duration_seconds||5}s na tela</p><p class="hint">${esc((o.social_platform==='tiktok'?'TikTok':'Instagram')+' @'+(o.social_handle||''))}</p><p class="quote">| @${esc(o.social_handle||'')} · ${esc(o.message)}</p><hr class="divider"><div class="row"><span>Valor total</span><strong>${money(o.price_cents)}</strong></div></div>${paymentPanel}<a class="btn secondary full" style="margin-top:10px" href="#${privateHash(o)}">Acompanhar meu recado →</a><p class="hint"><a href="#termos">Ver termos e política de reembolso</a></p><button class="btn ghost full" id="copy-tracking">Copiar link privado</button></section>`;
 $('#mp-checkout-order')?.addEventListener('click',async e=>{const button=e.currentTarget;button.disabled=true;button.textContent='Abrindo pagamento…';try{const checkout=await api('payment.checkout',{kind:'order',code:o.code,trackingToken:o.trackingToken});location.assign(checkout.checkoutUrl)}catch(error){toast(error.message);button.disabled=false;button.textContent='Continuar para pagamento →'}});
 $('#copy-tracking')?.addEventListener('click',()=>copy(location.origin+location.pathname+'#'+privateHash(o)))
}
function renderOrder(o,history=o.history||[]){const rejected=o.review==='rejected';if(trackingPoll)clearInterval(trackingPoll);const orderHash=location.hash;trackingPoll=setInterval(async()=>{if(location.hash!==orderHash)return;try{const fresh=await api('lookup',{code:o.code,trackingToken:o.trackingToken});const clean=value=>{const{trackingToken,history:ignored,...rest}=value;return rest};if(JSON.stringify(clean(fresh.order))!==JSON.stringify(clean(o))||JSON.stringify(fresh.history||[])!==JSON.stringify(history)){const next=remember(fresh.order,o.trackingToken,fresh.history||[]);renderOrder(next,fresh.history||[])}}catch{}},30000);app.innerHTML=`<section class="narrow tracking"><div class="eyebrow">Hocco Message · minha mensagem</div><h1 class="section-title">${o.delivery==='published'?'Seu recado<br><em>está no ar!</em>':'Seu recado está<br><em>a caminho.</em>'}</h1><p class="subheading">${esc(o.code)} · posição ${o.slot} · ${badge(o)}</p><div class="paper"><strong>${esc(o.name)}</strong><p class="hint">${esc((o.social_platform==='tiktok'?'TikTok':'Instagram')+' @'+(o.social_handle||''))}</p><p class="quote">| @${esc(o.social_handle||'')} · ${esc(o.message)}</p><div class="row"><span class="hint">${esc(o.episode)} · até ${o.publication_deadline?new Date(o.publication_deadline).toLocaleString('pt-BR'):'a definir'} · ${o.display_duration_seconds||5}s</span><strong>${money(o.price_cents)}</strong></div></div>${rejected?`<div class="note"><strong>Mensagem reprovada</strong><p>${esc(o.reason)}</p>${o.payment==='confirmed'?'Devolução pendente.':o.payment==='refunded'?'Devolução registrada.':'Não há pagamento confirmado.'}</div>`:`<ol class="timeline"><li class="done">Mensagem recebida</li><li class="${o.review==='approved'?'done':''}">Curadoria aprovada</li><li class="${o.payment==='confirmed'?'done':''}">Pagamento confirmado<small>${o.payment_claimed&&o.payment!=='confirmed'?'Você informou o pagamento. A equipe ainda precisa conferir.':'Confirmação independente da curadoria.'}</small></li><li class="${o.review==='approved'&&o.payment==='confirmed'?'done':''}">Fila de edição<small>Duas mensagens por tela; cada uma começa com |.</small></li><li class="${o.delivery==='published'?'done':''}">Mensagem veiculada</li></ol>`}${o.delivery==='published'?`<a class="btn purple full" href="${esc(o.video_url)}" target="_blank" rel="noopener noreferrer">▶ Ver minha mensagem no YouTube</a><p class="hint">${o.notification==='sent'?'Aviso enviado pelo WhatsApp.':'A equipe enviará o aviso pelo WhatsApp se você tiver autorizado esse contato.'}</p>`:!rejected?`<a class="btn secondary full" href="#${privateHash(o,'pagamento')}">Ver pagamento</a>`:''}${history.length?`<h2 class="history-title">Histórico deste comentário</h2><ol class="timeline status-history">${history.map(h=>`<li class="done">${esc(historyLabel(h.action))}${h.action==='reject'&&h.detail?.reason?`<small>Motivo: ${esc(h.detail.reason)}</small>`:''}<small>${new Date(h.created_at).toLocaleString('pt-BR')}</small></li>`).join('')}</ol>`:''}${o.reminder_active?'<button class="btn ghost full" id="stop-reminders">Parar lembretes a cada 2 dias</button>':''}<button class="btn ghost full" id="copy-tracking">Copiar link privado</button><a class="btn ghost" href="#acompanhar">← Meus pedidos</a></section>`;$('#copy-tracking').onclick=()=>copy(location.origin+location.pathname+'#'+privateHash(o));$('#stop-reminders')?.addEventListener('click',async()=>{if(!confirm('Parar os lembretes da ofensiva HOCCO?'))return;try{const result=await api('reminder_optout',{code:o.code,trackingToken:o.trackingToken});o.reminder_active=false;remember(o,o.trackingToken,result.history||history);renderOrder(o,result.history||history);toast('Lembretes cancelados.')}catch(e){toast(e.message)}})}
async function copy(text,notice='Link copiado. Guarde-o com você.'){try{await navigator.clipboard.writeText(text);toast(notice)}catch{openDialog(`<div class="dialog-top"><h2>Copie o conteúdo</h2>${closeButton}</div><textarea readonly aria-label="Conteúdo para copiar">${esc(text)}</textarea><p class="hint">Copie e guarde este link.</p>`)}}
function runScreenTransition(update,element=app,direction='forward'){
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return update();
 if(typeof document.startViewTransition==='function'){
  document.documentElement.dataset.hoccoDirection=direction;
  const transition=document.startViewTransition(()=>update());
  transition.finished.then(()=>delete document.documentElement.dataset.hoccoDirection,()=>delete document.documentElement.dataset.hoccoDirection);
  return transition;
 }
 const className=direction==='back'?'screen-swipe-back':'screen-swipe-forward';
 element.classList.remove('screen-swipe-back','screen-swipe-forward');
 element.classList.add(className);
 const result=update();
 setTimeout(()=>element.classList.remove(className),520);
 return result;
}
const routeRank=hash=>({inicio:0,enviar:1,pagamento:2,acompanhar:3,perfil:4,termos:5,privacidade:5,'previna-se':5}[(hash||'inicio').split('/')[0]]??2);
let previousRoute=location.hash.slice(1)||'inicio',exitBackUntil=0;
if(previousRoute==='inicio'&&!history.state?.hoccoExitGuard)history.pushState({...history.state,hoccoExitGuard:true},'',location.href);
window.addEventListener('popstate',event=>{const currentRoute=location.hash.slice(1)||'inicio';if(currentRoute!=='inicio'||event.state?.hoccoExitGuard)return;const now=Date.now();if(now<exitBackUntil){exitBackUntil=0;return}exitBackUntil=now+2000;toast('Pressione voltar novamente para sair.');history.pushState({...history.state,hoccoExitGuard:true},'',location.href)});
window.addEventListener('hashchange',()=>{if(trackingPoll)clearInterval(trackingPoll);const nextRoute=location.hash.slice(1)||'inicio',direction=routeRank(nextRoute)<routeRank(previousRoute)?'back':'forward';previousRoute=nextRoute;runScreenTransition(()=>render(),app,direction);window.scrollTo({top:0,behavior:'instant'})});render();
function renderPolicy(key){
 const doc=policyDocs[key];
 app.innerHTML=`<section class="legal-page"><div class="eyebrow">HOCCO · transparência</div><h1 class="section-title">${esc(doc.title)}</h1><p class="subheading">${esc(doc.intro)}</p><div class="legal-version">Versão ${LEGAL_VERSION} · ${LEGAL_DATE}</div><nav class="policy-tabs" aria-label="Documentos">${Object.entries(policyDocs).map(([id,d])=>`<a href="#${id}" ${id===key?'aria-current="page"':''}>${esc(d.title)}</a>`).join('')}</nav><div class="legal-summary"><h2>O essencial</h2><ul>${doc.summary.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div><article class="legal-text">${doc.sections.map(([title,body])=>`<section><h2>${esc(title)}</h2><p>${esc(body)}</p></section>`).join('')}</article><details class="rules"><summary>Referências oficiais consultadas</summary><ul>${legalSources.map(([title,url])=>`<li><a href="${url}" target="_blank" rel="noopener">${esc(title)} ↗</a></li>`).join('')}</ul></details><div class="legal-bottom"><a href="#enviar" class="btn purple">Voltar à minha mensagem →</a><button class="btn secondary" id="print-policy">Imprimir / salvar texto</button></div><p class="hint">O aceite dos termos e autorizações é registrado junto ao pedido no servidor.</p></section>`;
 $('#print-policy').onclick=()=>window.print();
}
